result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/dimcheck/dimensions.py", "content": """"Dimension vectors and arithmetic for dimcheck.

A dimension is a mapping from base-dimension names (mass, length, time, ...)
to integer exponents.  Dimensions support multiplication, division,
integer/fractional powers, and square roots (which halve exponents and refuse
odd exponents).
"""

from __future__ import annotations

import math

BASE_DIMENSIONS = ("mass", "length", "time", "current", "temperature", "amount", "luminosity")

DIMENSIONLESS = Dimension({})


class Dimension:
    """A vector of exponents over base dimensions."""

    __slots__ = ("exponents",)

    def __init__(self, exponents=None):
        self.exponents = {
            dim: int(exp) for dim, exp in dict(exponents or {}).items() if exp
        }

    # -- algebra ---------------------------------------------------------
    def __mul__(self, other):
        if not isinstance(other, Dimension):
            return NotImplemented
        result = dict(self.exponents)
        for dim, exp in other.exponents.items():
            result[dim] = result.get(dim, 0) + exp
        return Dimension(result)

    def __truediv__(self, other):
        if not isinstance(other, Dimension):
            return NotImplemented
        result = dict(self.exponents)
        for dim, exp in other.exponents.items():
            result[dim] = result.get(dim, 0) - exp
        return Dimension(result)

    def __pow__(self, exponent):
        exponent = _require_number(exponent)
        return Dimension({dim: exp * exponent for dim, exp in self.exponents.items()})

    def sqrt(self):
        """Half every exponent; odd exponents are a dimensional error."""
        for dim, exp in self.exponents.items():
            if exp % 2 != 0:
                raise DimensionOddRoot(
                    f"cannot take sqrt of dimension with odd exponent for "
                    f"'{dim}': {format_dimension(self)}"
                )
        return Dimension({dim: exp // 2 for dim, exp in self.exponents.items()})

    # -- comparison / misc -----------------------------------------------
    def __eq__(self, other):
        if not isinstance(other, Dimension):
            return NotImplemented
        return self.canonical() == other.canonical()

    def __hash__(self):
        return hash(self.canonical())

    def canonical(self):
        return tuple(sorted(self.exponents.items()))

    def is_dimensionless(self):
        return not self.exponents

    def __repr__(self):
        return f"Dimension({format_dimension(self)!r})"


def _require_number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"dimensional exponent must be a number, got {value!r}")
    return value


class DimensionOddRoot(Exception):
    """Raised when sqrt() is applied to a dimension with an odd exponent."""


# --------------------------------------------------------------------------
# Named dimensions: canonical spellings used to render friendly messages.
# --------------------------------------------------------------------------
NAMED_DIMENSIONS = {
    "dimensionless": Dimension({}),
    "mass": Dimension({"mass": 1}),
    "length": Dimension({"length": 1}),
    "time": Dimension({"time": 1}),
    "speed": Dimension({"length": 1, "time": -1}),
    "velocity": Dimension({"length": 1, "time": -1}),
    "acceleration": Dimension({"length": 1, "time": -2}),
    "momentum": Dimension({"mass": 1, "length": 1, "time": -1}),
    "force": Dimension({"mass": 1, "length": 1, "time": -2}),
    "energy": Dimension({"mass": 1, "length": 2, "time": -2}),
    "power": Dimension({"mass": 1, "length": 2, "time": -3}),
    "frequency": Dimension({"time": -1}),
}


def name_of(dimension):
    """Return the registered name of *dimension*, or None."""
    for name, candidate in NAMED_DIMENSIONS.items():
        if candidate == dimension:
            return name
    return None


def format_dimension(dimension):
    """Human-readable form, e.g. 'energy [mass^1 length^2 time^-2]'."""
    parts = [
        f"{dim}^{exp}" if exp != 1 else dim
        for dim, exp in sorted(dimension.exponents.items())
    ]
    vector = " ".join(parts) if parts else "dimensionless"
    name = name_of(dimension)
    if name and name != "dimensionless":
        return f"{name} [{vector}]"
    return f"[{vector}]"
