from __future__ import annotations

import ast

from .dimensions import DIMENSIONLESS, Dimension, DimensionOddRoot, format_dimension

__all__ = ["check", "parse_table", "DimensionMismatch", "UnknownSymbol", "FormulaSyntaxError"]


class DimensionMismatch(Exception):
    """Raised when two sub-expressions (or the two sides of '=') disagree."""


class UnknownSymbol(KeyError):
    """A symbol is missing from the symbol table (KeyError subclass)."""

    def __str__(self):
        return f"unknown symbol {self.args[0]!r} in symbol table"


class FormulaSyntaxError(ValueError):
    """The formula string could not be parsed."""


_ALLOWED_CALLS = {"sqrt"}


def parse_table(table):
    """Normalise a symbol table: values may be Dimension objects or
    dimension-expression strings like 'mass*length/time**2'."""
    parsed = {}
    for name, value in table.items():
        if isinstance(value, Dimension):
            parsed[name] = value
        elif isinstance(value, str):
            parsed[name] = _evaluate(ast.parse(value, mode="eval").body, {})
        else:
            raise TypeError(f"table entry for {name!r} must be a Dimension or str")
    return parsed


def check(formula, table):
    """Check 'lhs = rhs' dimensionally.  Returns True or raises.

    Raises:
        DimensionMismatch: sides (or '+'/'-' operands) have different dimensions.
        UnknownSymbol: a name is not in *table*.
        FormulaSyntaxError: the formula cannot be parsed.
    """
    table = parse_table(table)
    lhs_src, sep, rhs_src = formula.partition("=")
    if not sep:
        raise FormulaSyntaxError(f"formula must contain '=': {formula!r}")
    try:
        lhs = ast.parse(lhs_src, mode="eval")
        rhs = ast.parse(rhs_src, mode="eval")
    except SyntaxError as exc:
        raise FormulaSyntaxError(f"cannot parse formula {formula!r}: {exc}") from None

    left = _evaluate(lhs.body, table)
    right = _evaluate(rhs.body, table)
    if left != right:
        raise DimensionMismatch(
            f"sides of '=' disagree: LHS is {format_dimension(left)}, "
            f"RHS is {format_dimension(right)}"
        )
    return True


# --------------------------------------------------------------------------
# Bottom-up dimension evaluation over the AST
# --------------------------------------------------------------------------
def _evaluate(node, table):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, table)

    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise FormulaSyntaxError(f"unsupported literal {node.value!r}")
        return DIMENSIONLESS  # numeric literals are dimensionless

    if isinstance(node, ast.Name):
        try:
            return table[node.id]
        except KeyError:
            raise UnknownSymbol(node.id) from None

    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        return _evaluate(node.operand, table)

    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, table)
        right = _evaluate(node.right, table)
        op = node.op
        if isinstance(op, ast.Add) or isinstance(op, ast.Sub):
            symbol = "+" if isinstance(op, ast.Add) else "-"
            if left != right:
                raise DimensionMismatch(
                    f"operands of '{symbol}' disagree: "
                    f"{format_dimension(left)} vs {format_dimension(right)}"
                )
            return left
        if isinstance(op, ast.Mult):
            return left * right
        if isinstance(op, ast.Div):
            return left / right
        if isinstance(op, ast.Pow):
            if not right.is_dimensionless():
                raise DimensionMismatch(
                    f"exponent must be dimensionless, got {format_dimension(right)}"
                )
            exponent = _literal_number(node.right)
            return left ** exponent
        raise FormulaSyntaxError(f"unsupported binary operator: {ast.dump(op)}")

    if isinstance(node, ast.Call):
        func = node.func
        if not (isinstance(func, ast.Name) and func.id in _ALLOWED_CALLS):
            raise FormulaSyntaxError("only sqrt(...) calls are supported")
        if len(node.args) != 1 or node.keywords:
            raise FormulaSyntaxError("sqrt takes exactly one positional argument")
        return _evaluate(node.args[0], table).sqrt()

    raise FormulaSyntaxError(f"unsupported syntax: {ast.dump(node)}")


def _literal_number(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) \
            and not isinstance(node.value, bool):
        return node.value
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return -_literal_number(node.operand)
    raise FormulaSyntaxError("exponent must be a numeric literal")
